import { prisma } from "@/lib/prisma";
import { requireAuth } from "@/lib/auth";
import { NewTaskForm } from "./form";

export default async function NovaTaskPage({
  searchParams,
}: {
  searchParams: Promise<{ projectId?: string }>;
}) {
  const user = await requireAuth();
  const params = await searchParams;

  const [sectors, users, project] = await Promise.all([
    prisma.sector.findMany({
      where: { companyId: user.companyId, deletedAt: null },
      orderBy: { name: "asc" },
      select: { id: true, name: true },
    }),
    prisma.user.findMany({
      where: { companyId: user.companyId, isActive: true, deletedAt: null },
      orderBy: { name: "asc" },
      select: { id: true, name: true },
    }),
    params.projectId
      ? prisma.project.findFirst({
          where: { id: params.projectId, companyId: user.companyId, deletedAt: null },
          select: { id: true, name: true, client: { select: { name: true } } },
        })
      : null,
  ]);

  return <NewTaskForm sectors={sectors} users={users} project={project ?? null} />;
}
